using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

// --- Tool implementations ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
static async Task<string> SearchWeb(
    [Description("The search query to look up")] string query)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

    // Use DuckDuckGo Instant Answer API (no key required)
    var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
    try
    {
        var doc = await http.GetFromJsonAsync<JsonElement>(url);
        var results = new List<string>();

        // Collect the abstract
        var abs = doc.GetProperty("Abstract").GetString();
        if (!string.IsNullOrWhiteSpace(abs))
            results.Add($"[Summary] {abs}");

        // Collect related topics
        if (doc.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var topic in topics.EnumerateArray().Take(5))
            {
                if (topic.TryGetProperty("Text", out var text))
                    results.Add($"[Related] {text.GetString()}");
            }
        }

        return results.Count > 0
            ? string.Join("\n\n", results)
            : $"No detailed results found for '{query}'. Try rephrasing the query.";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

[Description("Save a research note for later summarization.")]
string TakeNote(
    [Description("The note content to save")] string note)
{
    notes.Add(note);
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n---\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

// --- Agent setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(TakeNote),
    AIFunctionFactory.Create(GetNotes),
};

var systemPrompt = """
    You are a research agent. Your job is to research a topic thoroughly using the tools available.

    Workflow:
    1. Break the topic into sub-questions.
    2. Use SearchWeb to find information for each sub-question.
    3. Use TakeNote to record key findings as you go.
    4. After gathering enough information, use GetNotes to review your notes.
    5. Produce a well-structured summary of your research findings.

    Be thorough but concise. Cite the sources of information when possible.
    """;

// --- Main loop ---

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (.NET 10)    ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notes.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary:\n\n{topic}"),
    };

    Console.WriteLine("\n🔍 Researching... (the agent will search the web and take notes)\n");

    var response = await client.GetResponseAsync(messages, new ChatOptions { Tools = tools });

    Console.WriteLine("═══════════════ Research Summary ═══════════════");
    Console.WriteLine(response.Text);
    Console.WriteLine("════════════════════════════════════════════════");
    Console.WriteLine($"\n📝 Notes taken during research: {notes.Count}");
}

Console.WriteLine("\nGoodbye!");

